/* @lc app=leetcode id=3302 lang=kotlin */ class Solution { fun validSequence(word1: String, word2: String): IntArray = word2.length.let { m -> (m - 1 downTo 0).runningFold(word1.length) { p, t -> if (p < 0) -1 else word1.lastIndexOf(word2[t], p - 1) }.reversed().let { e -> ArrayList<Int>().let { res -> word1.indices.fold(0 to false) { (j, sk), i -> if (j == m) j to sk else if (word1[i] == word2[j]) (j + 1 to sk).also { res.add(i) } else if (!sk && e[j + 1] > i) (j + 1 to true).also { res.add(i) } else j to sk }.let { if (res.size == m) res.toIntArray() else IntArray(0) } } } } }